m = gp.Model('CoffeeCabinetAllocation')
x_vars = m.addVars(cabinets, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((value[prod] * x_vars[cab, prod] for cab in cabinets for prod in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((weight[prod] * x_vars[cab, prod] for prod in products)) <= capacity[cab] for cab in cabinets), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')
